import{_ as t,a as d,o as a,a6 as n}from"./chunks/framework.CJDy2q7X.js";const m=JSON.parse('{"title":"CMS Page — Detail","description":"","frontmatter":{"outline":false,"examples":[{"id":"admin-cms-pages-detail","title":"CMS Page Detail","description":"Returns a single CMS page with the full htmlContent body, all translations, and channels. translations and channels are field-selectable connections — query them via edges { node { … } }. The id argument is the IRI from the listing node.","query":"query CmsPage($id: ID!) {\\n  adminCmsPage(id: $id) {\\n    id\\n    _id\\n    urlKey\\n    pageTitle\\n    htmlContent\\n    metaTitle\\n    metaKeywords\\n    metaDescription\\n    layout\\n    previewUrl\\n    locale\\n    channel\\n    channels {\\n      edges {\\n        node {\\n          id\\n          code\\n          name\\n        }\\n      }\\n    }\\n    translations {\\n      edges {\\n        node {\\n          locale\\n          pageTitle\\n          urlKey\\n          htmlContent\\n          metaTitle\\n          metaKeywords\\n          metaDescription\\n        }\\n      }\\n    }\\n  }\\n}\\n","variables":"{\\n  \\"id\\": \\"/api/admin/cms/pages/1\\"\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"adminCmsPage\\": {\\n      \\"id\\": \\"/api/admin/cms/pages/1\\",\\n      \\"_id\\": 1,\\n      \\"urlKey\\": \\"about-us\\",\\n      \\"pageTitle\\": \\"About Us\\",\\n      \\"htmlContent\\": \\"<div class=\\\\\\"static-container\\\\\\">\\\\r\\\\n<div class=\\\\\\"mb-5\\\\\\">We are dedicated to providing high-quality products and services to our customers. Our team is passionate about innovation and customer satisfaction. We believe in transparency, integrity, and building long-term relationships with our users.</div>\\\\r\\\\n</div>\\",\\n      \\"metaTitle\\": \\"about us\\",\\n      \\"metaKeywords\\": \\"aboutus\\",\\n      \\"metaDescription\\": \\"\\",\\n      \\"layout\\": null,\\n      \\"previewUrl\\": \\"https://your-domain.com/page/about-us\\",\\n      \\"locale\\": \\"en\\",\\n      \\"channel\\": \\"default\\",\\n      \\"channels\\": {\\n        \\"edges\\": [\\n          {\\n            \\"node\\": {\\n              \\"id\\": \\"/api/admin_cms_page_channels/1\\",\\n              \\"code\\": \\"default\\",\\n              \\"name\\": \\"Default\\"\\n            }\\n          }\\n        ]\\n      },\\n      \\"translations\\": {\\n        \\"edges\\": [\\n          {\\n            \\"node\\": {\\n              \\"locale\\": \\"ar\\",\\n              \\"pageTitle\\": \\"معلومات عنا\\",\\n              \\"urlKey\\": \\"about-us\\",\\n              \\"htmlContent\\": \\"<div class=\\\\\\"static-container\\\\\\">...</div>\\",\\n              \\"metaTitle\\": \\"معلومات عنا\\",\\n              \\"metaKeywords\\": \\"معلومات عنا\\",\\n              \\"metaDescription\\": \\"معلومات عنا\\"\\n            }\\n          },\\n          {\\n            \\"node\\": {\\n              \\"locale\\": \\"en\\",\\n              \\"pageTitle\\": \\"About Us\\",\\n              \\"urlKey\\": \\"about-us\\",\\n              \\"htmlContent\\": \\"<div class=\\\\\\"static-container\\\\\\">...</div>\\",\\n              \\"metaTitle\\": \\"about us\\",\\n              \\"metaKeywords\\": \\"aboutus\\",\\n              \\"metaDescription\\": \\"\\"\\n            }\\n          }\\n        ]\\n      }\\n    }\\n  }\\n}\\n"}]},"headers":[],"relativePath":"api/graphql-api/admin/cms/pages/queries/detail.md","filePath":"api/graphql-api/admin/cms/pages/queries/detail.md","lastUpdated":1787290888000}'),o={name:"api/graphql-api/admin/cms/pages/queries/detail.md"};function i(c,e,r,l,s,h){return a(),d("div",null,e[0]||(e[0]=[n('<h1 id="cms-page-—-detail" tabindex="-1">CMS Page — Detail <a class="header-anchor" href="#cms-page-—-detail" aria-label="Permalink to &quot;CMS Page — Detail&quot;">​</a></h1><p>Equivalent to <a href="/api/rest-api/admin/cms/pages-detail.html"><code>GET /api/admin/cms/pages/{id}</code></a>.</p><p>For what CMS Pages are and how multi-locale and multi-channel work, see the <a href="/api/graphql-api/admin/cms/pages/">CMS Pages overview</a>.</p><h2 id="operation" tabindex="-1">Operation <a class="header-anchor" href="#operation" aria-label="Permalink to &quot;Operation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operation</th><th>Type</th></tr></thead><tbody><tr><td><code>adminCmsPage(id: ID!)</code></td><td>Query</td></tr></tbody></table><p>The <code>id</code> argument is the <strong>IRI</strong> (<code>/api/admin/cms/pages/{id}</code>) — the same value returned as <code>node.id</code> on the <a href="/api/graphql-api/admin/cms/pages/queries/list.html">listing</a>. A bare numeric ID is not accepted.</p><h2 id="fields" tabindex="-1">Fields <a class="header-anchor" href="#fields" aria-label="Permalink to &quot;Fields&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Notes</th></tr></thead><tbody><tr><td><code>id</code></td><td><code>ID</code></td><td>IRI.</td></tr><tr><td><code>_id</code></td><td><code>Int</code></td><td>Numeric page ID.</td></tr><tr><td><code>urlKey</code></td><td><code>String</code></td><td>URL slug for the active locale.</td></tr><tr><td><code>pageTitle</code></td><td><code>String</code></td><td>Title for the active locale.</td></tr><tr><td><code>htmlContent</code></td><td><code>String</code></td><td>The full page HTML body for the active locale.</td></tr><tr><td><code>metaTitle</code> / <code>metaKeywords</code> / <code>metaDescription</code></td><td><code>String</code></td><td>SEO fields.</td></tr><tr><td><code>layout</code></td><td><code>String</code></td><td>Page layout identifier.</td></tr><tr><td><code>previewUrl</code></td><td><code>String</code></td><td>Live storefront URL for the page (the &quot;View&quot; action).</td></tr><tr><td><code>locale</code> / <code>channel</code></td><td><code>String</code></td><td>Resolved locale / channel.</td></tr><tr><td><code>channels</code></td><td>Connection</td><td>Every assigned channel — query via <code>channels { edges { node { … } } }</code>.</td></tr><tr><td><code>translations</code></td><td>Connection</td><td>Per-locale content — query via <code>translations { edges { node { … } } }</code>.</td></tr></tbody></table><h3 id="channels-—-connection" tabindex="-1"><code>channels</code> — connection <a class="header-anchor" href="#channels-—-connection" aria-label="Permalink to &quot;`channels` — connection&quot;">​</a></h3><p>A field-selectable Relay connection. Each <code>node</code> exposes:</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Notes</th></tr></thead><tbody><tr><td><code>id</code></td><td><code>ID</code></td><td>Channel IRI (e.g. <code>/api/admin_cms_page_channels/1</code>).</td></tr><tr><td><code>code</code></td><td><code>String</code></td><td>Channel code.</td></tr><tr><td><code>name</code></td><td><code>String</code></td><td>Channel display name.</td></tr></tbody></table><h3 id="translations-—-connection" tabindex="-1"><code>translations</code> — connection <a class="header-anchor" href="#translations-—-connection" aria-label="Permalink to &quot;`translations` — connection&quot;">​</a></h3><p>A field-selectable Relay connection — one entry per authored locale. Each <code>node</code> exposes:</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Notes</th></tr></thead><tbody><tr><td><code>locale</code></td><td><code>String</code></td><td>Locale code for this translation.</td></tr><tr><td><code>pageTitle</code></td><td><code>String</code></td><td>Title in this locale.</td></tr><tr><td><code>urlKey</code></td><td><code>String</code></td><td>URL slug in this locale.</td></tr><tr><td><code>htmlContent</code></td><td><code>String</code></td><td>The full page body for this locale.</td></tr><tr><td><code>metaTitle</code> / <code>metaKeywords</code> / <code>metaDescription</code></td><td><code>String</code></td><td>SEO fields in this locale.</td></tr></tbody></table><p><code>translations</code> returns one entry per authored locale; the <code>htmlContent</code> inside a translation is the full body for that locale.</p><h3 id="connections-not-opaque-json" tabindex="-1">Connections, Not Opaque JSON <a class="header-anchor" href="#connections-not-opaque-json" aria-label="Permalink to &quot;Connections, Not Opaque JSON&quot;">​</a></h3><p><code>channels</code> and <code>translations</code> are Relay connections — select them with <code>edges { node { … } }</code> and take only the sub-fields you need. Over REST the same data arrives as plain JSON arrays, so the two transports are not shape-compatible.</p><p>Both nested node types carry a <strong>routeless <code>id</code></strong> — <code>/api/admin_cms_page_translations/&lt;id&gt;</code> and <code>/api/admin_cms_page_channels/&lt;id&gt;</code>. Neither is a queryable path; read <code>_id</code> instead.</p><h2 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;Errors&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Code</th><th>Cause</th></tr></thead><tbody><tr><td>Not found</td><td>Page not found.</td></tr></tbody></table>',20)]))}const u=t(o,[["render",i]]);export{m as __pageData,u as default};
